type Infos = { id: number; photo?: string; credit?: string; obs: number; pts: [number, number][]; nomFr?: string } | "erreur" | "absent" | undefined
const cache = new Map<string, Infos>()

function useInat(nom: string | null) {
    const [, maj] = React.useState(0)
    React.useEffect(() => {
        if (!nom || cache.has(nom)) return
        cache.set(nom, undefined)
        let fini = false
        ;(async () => {
            try {
                const t = await (await fetch(`https://api.inaturalist.org/v1/taxa?q=${encodeURIComponent(nom)}&rank=genus&per_page=10&locale=fr`)).json()
                const tx = (t.results || []).find((r) => r.name === nom && r.iconic_taxon_name === "Plantae") || (t.results || []).find((r) => r.name === nom)
                if (!tx) { cache.set(nom, "absent"); if (!fini) maj((x) => x + 1); return }
                const o = await (await fetch(`https://api.inaturalist.org/v1/observations?taxon_id=${tx.id}&quality_grade=research&captive=false&geo=true&per_page=200&order_by=votes`)).json()
                const pts = (o.results || []).map((r) => r.geojson?.coordinates).filter(Boolean)
                const nomFr = tx.preferred_common_name && sansAccent(tx.preferred_common_name) !== sansAccent(nom) ? tx.preferred_common_name : undefined
                cache.set(nom, { id: tx.id, photo: tx.default_photo?.medium_url?.replace("/medium.", "/large."), credit: tx.default_photo?.attribution, obs: tx.observations_count || 0, pts, nomFr })
            } catch (e) {
                cache.set(nom, "erreur")
            }
            if (!fini) maj((x) => x + 1)
        })()
        return () => { fini = true; maj((x) => x + 1) }
    }, [nom])
    return nom ? cache.get(nom) : undefined
}

function Culture({ c }: { c: [string, string, string, string, string, number, string, string, number] }) {
    const [croit, repos, expo, tmin, eau, mel, mult, flo, diff] = c
    const lignes: [string, React.ReactNode][] = [
        ["Croissance", croit], ["Repos", repos], ["Exposition", expo], ["Minimum en hiver", tmin], ["Arrosage", eau],
        ["Substrat", <>{MELANGES[mel]} <a href="/guides/substrats" style={{ color: "inherit", whiteSpace: "nowrap" }}>Voir le guide →</a></>],
        ["Multiplication", /semis/i.test(mult) ? <>{mult} <a href="/guides/semis" style={{ color: "inherit", whiteSpace: "nowrap" }}>Guide des semis →</a></> : mult],
        ["Floraison", flo], ["Difficulté", DIFF[diff]],
    ]
    return (
        <div style={{ marginTop: 16, borderTop: "1px solid rgba(29,22,18,0.16)", paddingTop: 12 }}>
            <div style={{ fontSize: 15, fontWeight: 600 }}>Culture</div>
            <div style={{ display: "grid", gridTemplateColumns: "auto 1fr", gap: "6px 14px", marginTop: 8, fontSize: 14, lineHeight: 1.45 }}>
                {lignes.map(([k, v]) => <React.Fragment key={k}><span style={{ opacity: 0.6, whiteSpace: "nowrap" }}>{k}</span><span>{v}</span></React.Fragment>)}
            </div>
            <div style={{ fontSize: 12, opacity: 0.55, marginTop: 8 }}>Repères indicatifs pour une culture en serre ou sous abri en Bretagne, à adapter à vos conditions.</div>
        </div>
    )
}

function Especes({ n, l, q, source }: { n: string; l: [string, number, number, string]; q: string; source?: string }) {
    const [ref, nb, obs, liste] = l
    const sp = liste ? liste.split("|") : []
    const [ouvert, setOuvert] = React.useState(false)
    React.useEffect(() => setOuvert(false), [n])
    const montrer = ouvert || (q.length >= 3 && sp.some((e) => sansAccent(e).includes(q)))
    return (
        <div style={{ marginTop: 16, borderTop: "1px solid rgba(29,22,18,0.16)", paddingTop: 12 }}>
            <button onClick={() => setOuvert((o) => !o)} aria-expanded={montrer} style={{ all: "unset", cursor: "pointer", display: "flex", width: "100%", justifyContent: "space-between", alignItems: "center", gap: 10 }}>
                <span style={{ fontSize: 15 }}><strong style={{ fontWeight: 600 }}>{nb}</strong> {source ? (liste.includes(" subsp. ") ? "espèces et sous-espèces" : nb > 1 ? "espèces" : "espèce") : "espèces et sous-espèces selon J. Lodé"}</span>
                <svg width="12" height="12" viewBox="0 0 12 12" style={{ flex: "none", transform: montrer ? "rotate(180deg)" : "none", transition: "transform .2s" }}><path d="M2 4 L6 8 L10 4" fill="none" stroke="currentColor" strokeWidth="1.6" /></svg>
            </button>
            <div style={{ fontSize: 12.5, opacity: 0.6, marginTop: 3 }}>{source ? "Liste : " + source : `Taxonomie des Cactaceae, ${ref}${obs ? " · genre observé par l’auteur dans la nature" : ""}`}</div>
            {montrer && (
                <div style={{ marginTop: 10, maxHeight: 10 * 23 + 4, overflowY: "auto", overscrollBehavior: "contain", paddingRight: 6, borderBottom: sp.length > 10 ? "1px solid rgba(29,22,18,0.12)" : "none" }}>
                    {sp.map((e) => {
                        const vu = q.length >= 3 && sansAccent(e).includes(q)
                        return <div key={e} style={{ fontFamily: serif, fontSize: 14.5, lineHeight: "23px", height: 23, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", fontStyle: "italic", fontWeight: vu ? 700 : 400 }}>{n.charAt(0)}. {e.split(" subsp. ").map((m, i) => i ? <React.Fragment key={i}><span style={{ fontStyle: "normal", fontFamily: sans, fontSize: 12.5 }}> subsp. </span>{m}</React.Fragment> : m)}</div>
                    })}
                </div>
            )}
            {montrer && sp.length > 10 && <div style={{ fontSize: 12, opacity: 0.55, marginTop: 6 }}>Faites défiler pour voir les {sp.length} noms.</div>}
        </div>
    )
}

/**
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight auto
 */
export default function CarteMonde(props) {
    const { encre = "#1d1612", vert = "#4a7a36", accent = "#b5543a", fond = "#efe6d6" } = props
    const carteFond = "#f6f0e6", trait = "rgba(29,22,18,0.16)"
    const ref = React.useRef<HTMLDivElement>(null)
    const [w, setW] = React.useState(1000)
    React.useEffect(() => {
        const el = ref.current
        if (!el) return
        const ro = new ResizeObserver(() => setW(el.clientWidth))
        ro.observe(el)
        setW(el.clientWidth)
        return () => ro.disconnect()
    }, [])
    const [cat, setCat] = React.useState<"Tous" | Cat>("Tous")
    const [q, setQ] = React.useState("")
    const [sel, setSel] = React.useState<string | null>(null)
    const [survol, setSurvol] = React.useState<string | null>(null)
    const [ouverts, setOuverts] = React.useState<Record<string, boolean>>({})
    const [suggOuv, setSuggOuv] = React.useState(false)
    const infos = useInat(sel)
    const etroit = w < 760
    const qq = sansAccent(q.trim())
    const especes = (n: string) => (LODE[n]?.[3] ? LODE[n][3].split("|") : AUTRES[n] ? AUTRES[n][1].split("|") : [])
    const espTrouvee = (g: Genre) => (qq.length >= 3 ? especes(g.n).find((e) => sansAccent(g.n + " " + e).includes(qq) || sansAccent(e).includes(qq)) : undefined)
    const correspond = (g: Genre) => !qq || sansAccent(g.n).includes(qq) || g.pays.some((p) => sansAccent(p).includes(qq)) || sansAccent(g.zone).includes(qq) || !!espTrouvee(g)
    const visibles = GENRES.filter((g) => (cat === "Tous" || g.c === cat) && correspond(g))
    const g = GENRES.find((x) => x.n === sel) || null
    const choisir = (n: string) => { setSel((s) => (s === n ? null : n)); setSuggOuv(false) }
    const r = etroit ? (visibles.length > 120 ? 4.2 : 5) : visibles.length > 120 ? 3.5 : 4.4
    // ---- Vue zoomable (molette, pincement, glisser, boutons + / −)
    const BX = 0, BY = 4, BW = 1000, BH = 446
    type Vue = { x: number; y: number; w: number }
    // sur téléphone, cadre plus haut (presque carré) ouvert sur l'Atlantique, qu'on fait glisser
    const R = etroit ? 0.9 : BH / BW
    const WMAX = Math.min(BW, BH / R)
    const VUE0: Vue = etroit ? { x: 150, y: BY, w: WMAX } : { x: BX, y: BY, w: BW }
    const [vue, setVue] = React.useState<Vue>(VUE0)
    React.useEffect(() => { setVue(VUE0) }, [etroit])
    const vueRef = React.useRef(vue); vueRef.current = vue
    const svgRef = React.useRef<SVGSVGElement>(null)
    const WMIN = 70
    const borner = (v: Vue): Vue => {
        const w = Math.min(WMAX, Math.max(WMIN, v.w)), h = w * R
        return { w, x: Math.min(BX + BW - w, Math.max(BX, v.x)), y: Math.min(BY + BH - h, Math.max(BY, v.y)) }
    }
    const zoomer = (f: number, cx?: number, cy?: number) => setVue((v) => {
        const h = v.w * R
        const px = cx ?? v.x + v.w / 2, py = cy ?? v.y + h / 2
        const w = Math.min(WMAX, Math.max(WMIN, v.w / f))
        const k = w / v.w
        return borner({ w, x: px - (px - v.x) * k, y: py - (py - v.y) * k })
    })
    const versCarte = (clientX: number, clientY: number): [number, number] => {
        const el = svgRef.current!, b = el.getBoundingClientRect(), v = vueRef.current
        return [v.x + ((clientX - b.left) / b.width) * v.w, v.y + ((clientY - b.top) / b.height) * (v.w * R)]
    }
    React.useEffect(() => {
        const el = svgRef.current
        if (!el) return
        const roue = (e: WheelEvent) => {
            const v = vueRef.current
            if (e.deltaY > 0 && v.w >= WMAX - 1) return // tout dézoomé : on laisse la page défiler
            e.preventDefault()
            const [cx, cy] = versCarte(e.clientX, e.clientY)
            zoomer(Math.exp(-e.deltaY * (e.deltaMode === 1 ? 0.05 : 0.0018)), cx, cy)
        }
        el.addEventListener("wheel", roue, { passive: false })
        return () => el.removeEventListener("wheel", roue)
    }, [])
    const pointeurs = React.useRef(new Map<number, [number, number]>())
    const geste = React.useRef<{ d0: number; v0: Vue; c0: [number, number] } | null>(null)
    const bouge = React.useRef(0)
    const pDown = (e: React.PointerEvent) => {
        if (e.pointerType === "mouse" && e.button !== 0) return
        pointeurs.current.set(e.pointerId, [e.clientX, e.clientY])
        bouge.current = 0
        if (pointeurs.current.size === 2) {
            const [a, b] = Array.from(pointeurs.current.values())
            geste.current = { d0: Math.hypot(a[0] - b[0], a[1] - b[1]), v0: vueRef.current, c0: versCarte((a[0] + b[0]) / 2, (a[1] + b[1]) / 2) }
        }
    }
    const pMove = (e: React.PointerEvent) => {
        const prec = pointeurs.current.get(e.pointerId)
        if (!prec) return
        pointeurs.current.set(e.pointerId, [e.clientX, e.clientY])
        const el = svgRef.current!, b = el.getBoundingClientRect()
        if (pointeurs.current.size === 2 && geste.current) {
            const [a, c] = Array.from(pointeurs.current.values())
            const d = Math.hypot(a[0] - c[0], a[1] - c[1])
            const g0 = geste.current, w = Math.min(BW, Math.max(WMIN, (g0.v0.w * g0.d0) / Math.max(d, 1))), k = w / g0.v0.w
            const [cx, cy] = g0.c0
            setVue(borner({ w, x: cx - (cx - g0.v0.x) * k, y: cy - (cy - g0.v0.y) * k }))
            bouge.current += 10
            return
        }
        if (pointeurs.current.size !== 1 || vueRef.current.w >= BW - 1) return
        const dx = e.clientX - prec[0], dy = e.clientY - prec[1]
        bouge.current += Math.abs(dx) + Math.abs(dy)
        if (bouge.current > 4) {
            if (!el.hasPointerCapture(e.pointerId)) try { el.setPointerCapture(e.pointerId) } catch (er) {}
            const v = vueRef.current, k = v.w / b.width
            setVue(borner({ ...v, x: v.x - dx * k, y: v.y - dy * k }))
        }
    }
    const pUp = (e: React.PointerEvent) => { pointeurs.current.delete(e.pointerId); if (pointeurs.current.size < 2) geste.current = null }
    const clicCarte = (n: string) => { if (bouge.current > 6) return; choisir(n) }
    // en choisissant un genre depuis la liste ou la recherche, la carte se recentre dessus
    React.useEffect(() => {
        if (!g) return
        const [x, y] = pt(g.pts[0][0], g.pts[0][1])
        setVue((v) => {
            const w = Math.min(v.w, 320), h = w * R
            const dedans = x > v.x + v.w * 0.1 && x < v.x + v.w * 0.9 && y > v.y + h * 0.1 && y < v.y + v.w * R * 0.9
            return dedans && v.w <= 320 ? v : borner({ w, x: x - w / 2, y: y - h / 2 })
        })
    }, [sel])
    const echelle = vue.w / BW // pour garder points et textes à taille constante à l'écran
    const ficheRef = React.useRef<HTMLDivElement>(null)

    const puce = (actif: boolean): React.CSSProperties => ({
        fontFamily: sans, fontSize: 13, fontWeight: 500, padding: "7px 13px", cursor: "pointer", whiteSpace: "nowrap",
        border: `1px solid ${actif ? encre : "rgba(29,22,18,0.25)"}`, background: actif ? encre : "transparent", color: actif ? fond : encre, borderRadius: 0,
    })
    const nomEtiquette = survol || sel
    const gEtiq = GENRES.find((x) => x.n === nomEtiquette)
    const nbPays = new Set(GENRES.flatMap((x) => x.pays)).size

    // tailles exprimées en pixels écran, converties en unités de carte selon le zoom
    const u = vue.w / Math.max(w, 1)
    const rp = (etroit ? 5 : 4.5) * (visibles.length > 120 && vue.w > 600 ? 0.82 : 1)
    const point = (gg: Genre, x: number, y: number, key: string) => {
        const actif = gg.n === sel, sur = gg.n === survol
        return (
            <g key={key} style={{ cursor: "pointer" }} onClick={() => clicCarte(gg.n)} onMouseEnter={() => setSurvol(gg.n)} onMouseLeave={() => setSurvol(null)}>
                <circle cx={x} cy={y} r={rp * 2 * u} fill="transparent" />
                {actif && <circle cx={x} cy={y} r={rp * 2.4 * u} fill="none" stroke={accent} strokeWidth={1.3 * u} />}
                <circle cx={x} cy={y} r={(actif || sur ? rp * 1.3 : rp) * u} fill={actif ? accent : vert} fillOpacity={actif || sur ? 1 : 0.85} stroke={fond} strokeWidth={1 * u} />
            </g>
        )
    }
    const etiquetteSvg = (n: string, x: number, y: number, key: string) => {
        const droite = x < vue.x + vue.w * 0.82
        const dx = (rp * 2.6 + 3) * u
        return <text key={key} x={x + (droite ? dx : -dx)} y={y + 5 * u} textAnchor={droite ? "start" : "end"} fontFamily={serif} fontSize={16 * u} fontWeight={600} fontStyle="italic" fill={n === sel ? accent : encre} stroke={fond} strokeWidth={4 * u} strokeLinejoin="round" paintOrder="stroke" style={{ pointerEvents: "none" }}>{n}</text>
    }
    const positions = (gg: Genre) => gg.pts.map(([lo, la]) => pt(lo, la))
    const bouton = (t: string, aria: string, f: () => void, off = false) => (
        <button aria-label={aria} title={aria} onClick={f} disabled={off}
            style={{ all: "unset", boxSizing: "border-box", width: 36, height: 36, display: "flex", alignItems: "center", justifyContent: "center", background: carteFond, border: `1px solid rgba(29,22,18,0.3)`, color: encre, fontFamily: sans, fontSize: t.length > 1 ? 15 : 20, cursor: off ? "default" : "pointer", opacity: off ? 0.35 : 1, userSelect: "none" }}>{t}</button>
    )
    const zoomee = vue.w < WMAX - 1
    const deplacable = vue.w < BW - 1
    const carte = (
        <div style={{ position: "relative", border: `1px solid ${trait}`, background: fond, overflow: "hidden" }}>
            <svg ref={svgRef} viewBox={`${vue.x} ${vue.y} ${vue.w} ${vue.w * R}`} onPointerDown={pDown} onPointerMove={pMove} onPointerUp={pUp} onPointerCancel={pUp} onPointerLeave={(e) => { if (e.pointerType === "mouse") pUp(e) }}
                style={{ width: "100%", height: "auto", display: "block", touchAction: zoomee ? "none" : "pan-y", cursor: deplacable ? "grab" : "default", userSelect: "none" }}
                role="img" aria-label="Carte du monde des régions d'origine de genres de cactus, succulentes et bulbes">
                <path d={COTE_MONDE} fill="none" stroke={encre} strokeOpacity={0.8} strokeWidth={1} strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />
                {infos && typeof infos === "object" && infos.pts.map(([lo, la], i) => {
                    const [x, y] = pt(lo, la)
                    return <circle key={"o" + i} cx={x} cy={y} r={2.2 * u} fill={accent} fillOpacity={0.4} />
                })}
                {visibles.map((gg) => positions(gg).map(([x, y], i) => point(gg, x, y, gg.n + i)))}
                {gEtiq && (() => {
                    const vus: [number, number][] = []
                    return positions(gEtiq).map(([x, y], i) => {
                        if (vus.some(([a, b]) => Math.hypot(a - x, b - y) < 70 * u)) return null
                        vus.push([x, y])
                        return etiquetteSvg(gEtiq.n, x, y, "t" + i)
                    })
                })()}
            </svg>
            <div style={{ position: "absolute", top: 10, right: 10, display: "flex", flexDirection: "column", gap: 6 }}>
                {bouton("+", "Zoomer", () => zoomer(1.8), vue.w <= WMIN + 0.5)}
                {bouton("−", "Dézoomer", () => zoomer(1 / 1.8), !zoomee)}
                {bouton("⤢", etroit ? "Revenir à la vue de départ" : "Voir le monde entier", () => setVue(VUE0), !zoomee && Math.abs(vue.x - VUE0.x) < 1)}
            </div>
            <div style={{ position: "absolute", left: 10, bottom: 8, fontFamily: sans, fontSize: 11.5, color: encre, opacity: 0.6, pointerEvents: "none" }}>
                {etroit ? "Pincez pour zoomer, glissez pour vous déplacer" : "Molette pour zoomer, cliquer-glisser pour se déplacer"}
            </div>
        </div>
    )

    const recherche = (
        <div style={{ position: "relative", flex: etroit ? "1 1 100%" : "0 1 320px", minWidth: 0 }}>
            <svg width="16" height="16" viewBox="0 0 16 16" style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", opacity: 0.55 }}><circle cx="6.5" cy="6.5" r="5" fill="none" stroke={encre} strokeWidth="1.6" /><path d="M10.5 10.5 L15 15" stroke={encre} strokeWidth="1.6" /></svg>
            <input value={q} onChange={(e) => { setQ(e.target.value); setSuggOuv(true) }} onFocus={() => setSuggOuv(true)} onBlur={() => setTimeout(() => setSuggOuv(false), 150)}
                onKeyDown={(e) => { if (e.key === "Enter" && visibles.length) { choisir(visibles[0].n); (e.target as HTMLInputElement).blur() } if (e.key === "Escape") setQ("") }}
                placeholder="Genre, espèce ou pays" aria-label="Rechercher un genre, une espèce ou un pays"
                style={{ width: "100%", boxSizing: "border-box", fontFamily: sans, fontSize: 15, color: encre, background: carteFond, border: `1px solid rgba(29,22,18,0.3)`, borderRadius: 0, padding: "10px 34px 10px 36px", outline: "none" }} />
            {q && <button aria-label="Effacer" onClick={() => setQ("")} style={{ all: "unset", cursor: "pointer", position: "absolute", right: 10, top: "50%", transform: "translateY(-50%)", fontFamily: sans, fontSize: 18, lineHeight: 1, opacity: 0.6, padding: 4 }}>×</button>}
            {suggOuv && qq && (
                <div style={{ position: "absolute", left: 0, right: 0, top: "100%", zIndex: 5, background: carteFond, border: `1px solid rgba(29,22,18,0.3)`, borderTop: "none", maxHeight: 280, overflowY: "auto", boxShadow: "0 10px 24px rgba(29,22,18,0.12)" }}>
                    {visibles.length === 0 && <div style={{ fontFamily: sans, fontSize: 14, padding: "10px 14px", opacity: 0.65 }}>Aucun genre trouvé.</div>}
                    {visibles.slice(0, 12).map((x) => (
                        <button key={x.n} onMouseDown={(e) => e.preventDefault()} onClick={() => { choisir(x.n); ficheRef.current?.scrollIntoView?.({ behavior: "smooth", block: "nearest" }) }}
                            style={{ all: "unset", boxSizing: "border-box", cursor: "pointer", display: "flex", justifyContent: "space-between", gap: 12, width: "100%", padding: "9px 14px", borderBottom: `1px solid ${trait}` }}>
                            <span style={{ fontFamily: serif, fontStyle: "italic", fontSize: 16, color: encre }}>{x.n}{(() => { const e = !sansAccent(x.n).includes(qq) && espTrouvee(x); return e ? " " + e : "" })()}</span>
                            <span style={{ fontFamily: sans, fontSize: 12, color: encre, opacity: 0.6, textAlign: "right" }}>{x.c === "Succulentes" ? "Succulente" : x.c} · {x.pays.slice(0, 2).join(", ")}{x.pays.length > 2 ? "…" : ""}</span>
                        </button>
                    ))}
                </div>
            )}
        </div>
    )

    const etiquette = (t: string) => <div style={{ fontFamily: sans, fontSize: 11.5, fontWeight: 600, letterSpacing: 1.6, textTransform: "uppercase", color: vert }}>{t}</div>

    const fiche = (
        <div ref={ficheRef} style={{ background: carteFond, border: `1px solid ${trait}`, padding: etroit ? 20 : 28, fontFamily: sans, color: encre, boxSizing: "border-box" }}>
            {g ? (
                <>
                    {etiquette(NOM_CAT[g.c])}
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 12, marginTop: 6 }}>
                        <div style={{ fontFamily: serif, fontSize: etroit ? 30 : 36, lineHeight: 1.1, fontStyle: "italic", fontWeight: 600 }}>{g.n}</div>
                        <button onClick={() => setSel(null)} aria-label="Fermer la fiche" style={{ all: "unset", cursor: "pointer", fontSize: 22, opacity: 0.5, padding: "0 4px" }}>×</button>
                    </div>
                    {infos && typeof infos === "object" && infos.nomFr && <div style={{ fontSize: 14, opacity: 0.7, marginTop: 2 }}>{infos.nomFr}</div>}
                    <div style={{ fontSize: 15, marginTop: 12, lineHeight: 1.5 }}><span style={{ opacity: 0.6 }}>Origine · </span>{g.zone}</div>
                    <div style={{ fontSize: 14, marginTop: 4, lineHeight: 1.5, opacity: 0.75 }}>{g.pays.join(", ")}</div>
                    {g.note && <p style={{ fontSize: 16, lineHeight: 1.6, margin: "14px 0 0" }}>{g.note}</p>}
                    {CULTURE[g.n] && <Culture c={CULTURE[g.n]} />}
                    {LODE[g.n] && <Especes n={g.n} l={LODE[g.n]} q={qq} />}
                    {!LODE[g.n] && AUTRES[g.n] && <Especes n={g.n} l={["", AUTRES[g.n][1].split("|").length, 0, AUTRES[g.n][1]]} source={AUTRES[g.n][0]} q={qq} />}
                    <div style={{ marginTop: 18 }}>
                        {infos === undefined && <div style={{ aspectRatio: "4 / 3", background: "rgba(29,22,18,0.06)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 13, opacity: 0.7 }}>Chargement depuis iNaturalist…</div>}
                        {infos === "erreur" && <div style={{ fontSize: 13, opacity: 0.65 }}>iNaturalist ne répond pas pour le moment.</div>}
                        {infos === "absent" && <div style={{ fontSize: 13, opacity: 0.65, lineHeight: 1.5 }}>Ce genre n’existe pas sous ce nom sur iNaturalist, qui suit une autre classification. Essayez avec le nom d’une de ses espèces sur inaturalist.org.</div>}
                        {infos && typeof infos === "object" && (
                            <>
                                {infos.photo && (
                                    <figure style={{ margin: 0 }}>
                                        <img src={infos.photo} alt={g.n} loading="lazy" style={{ width: "100%", aspectRatio: "4 / 3", objectFit: "cover", display: "block", background: "rgba(29,22,18,0.06)" }} />
                                        <figcaption style={{ fontSize: 11.5, opacity: 0.6, marginTop: 6, lineHeight: 1.4 }}>{infos.credit} — via iNaturalist</figcaption>
                                    </figure>
                                )}
                                <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginTop: 14, fontSize: 14, lineHeight: 1.5 }}>
                                    <span style={{ flex: "none", display: "inline-block", width: 10, height: 10, borderRadius: 10, background: accent, opacity: 0.6 }} />
                                    <span><strong style={{ fontWeight: 600 }}>{infos.obs.toLocaleString("fr-FR")}</strong> observations sur iNaturalist{infos.pts.length ? ` ; les points clairs de la carte montrent ${infos.pts.length} plantes sauvages vérifiées.` : "."}</span>
                                </div>
                                <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginTop: 16 }}>
                                    <a href={`https://www.inaturalist.org/taxa/${infos.id}`} target="_blank" rel="noopener" style={{ ...puce(true), textDecoration: "none" }}>Fiche iNaturalist ↗</a>
                                    <a href={`https://www.inaturalist.org/observations?taxon_id=${infos.id}&quality_grade=research&captive=false&subview=map`} target="_blank" rel="noopener" style={{ ...puce(false), textDecoration: "none" }}>Carte des observations ↗</a>
                                </div>
                            </>
                        )}
                    </div>
                </>
            ) : (
                <>
                    {etiquette("Mode d'emploi")}
                    <div style={{ fontFamily: serif, fontSize: 26, lineHeight: 1.2, fontWeight: 600, marginTop: 8 }}>{GENRES.length} genres, {nbPays} pays</div>
                    <p style={{ fontSize: 16, lineHeight: 1.65, margin: "12px 0 0", opacity: 0.85 }}>
                        {etroit ? "Touchez" : "Cliquez sur"} un point de la carte, cherchez un nom ou ouvrez un continent : la fiche affiche l'aire d'origine, une photo et les observations faites dans la nature, grâce aux données ouvertes d'iNaturalist.
                    </p>
                    <p style={{ fontSize: 14, lineHeight: 1.6, margin: "10px 0 0", opacity: 0.8 }}>{Object.keys(CULTURE).length} genres phares ont une fiche de culture : saisons, exposition, arrosage et mélange conseillé, en lien avec nos guides.</p>
                    <div style={{ fontSize: 13, opacity: 0.65, marginTop: 18 }}>Pour commencer :</div>
                    <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginTop: 8 }}>
                        {["Lithops", "Ariocarpus", "Massonia", "Pachypodium", "Copiapoa", "Turbinicarpus"].map((n) => (
                            <button key={n} onClick={() => choisir(n)} style={{ ...puce(false), fontFamily: serif, fontStyle: "italic", fontSize: 15 }}>{n}</button>
                        ))}
                    </div>
                </>
            )}
        </div>
    )

    const liste = (
        <div style={{ fontFamily: sans, color: encre }}>
            {CONTINENTS.map(([cont, pays]) => {
                const lignes = pays.map((p) => [p, visibles.filter((x) => x.pays.includes(p))] as const).filter(([, l]) => l.length)
                if (!lignes.length) return null
                const nbG = new Set(lignes.flatMap(([, l]) => l.map((x) => x.n))).size
                const ouvert = !!qq || !!ouverts[cont]
                return (
                    <div key={cont} style={{ borderTop: `1px solid rgba(29,22,18,0.22)` }}>
                        <button onClick={() => setOuverts((o) => ({ ...o, [cont]: !ouvert }))} aria-expanded={ouvert}
                            style={{ all: "unset", boxSizing: "border-box", cursor: "pointer", width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, padding: "14px 0" }}>
                            <span style={{ fontFamily: serif, fontSize: 19, fontWeight: 600 }}>{cont}</span>
                            <span style={{ display: "flex", alignItems: "center", gap: 12, fontSize: 13, opacity: 0.7, whiteSpace: "nowrap" }}>
                                {lignes.length} pays · {nbG} genres
                                <svg width="12" height="12" viewBox="0 0 12 12" style={{ transform: ouvert ? "rotate(180deg)" : "none", transition: "transform .2s" }}><path d="M2 4 L6 8 L10 4" fill="none" stroke={encre} strokeWidth="1.6" /></svg>
                            </span>
                        </button>
                        {ouvert && (
                            <div style={{ paddingBottom: 18 }}>
                                {lignes.map(([p, l]) => (
                                    <div key={p} style={{ display: "flex", flexDirection: etroit ? "column" : "row", gap: etroit ? 2 : 16, padding: "8px 0", borderTop: `1px solid ${trait}` }}>
                                        <span style={{ fontSize: 14, fontWeight: 600, width: etroit ? "auto" : 130, flex: "none", paddingTop: 2 }}>{p}</span>
                                        <span style={{ display: "flex", flexWrap: "wrap", gap: "2px 12px" }}>
                                            {l.map((x) => (
                                                <button key={x.n} onClick={() => { choisir(x.n); if (etroit) ficheRef.current?.scrollIntoView?.({ behavior: "smooth", block: "start" }) }} onMouseEnter={() => setSurvol(x.n)} onMouseLeave={() => setSurvol(null)}
                                                    style={{ all: "unset", cursor: "pointer", fontFamily: serif, fontStyle: "italic", fontSize: 15.5, lineHeight: 1.6, color: x.n === sel ? accent : encre, textDecoration: x.n === sel ? "underline" : "none", textUnderlineOffset: 3 }}>{x.n}</button>
                                            ))}
                                        </span>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                )
            })}
            <div style={{ borderTop: `1px solid rgba(29,22,18,0.22)`, paddingTop: 12, fontSize: 12, opacity: 0.6, lineHeight: 1.5 }}>Aires d'origine simplifiées. Liste des cactus : index de Joël Lodé, Taxonomie des Cactaceae (vol. 3 à 6). Mésembs et caudex : Plants of the World Online (Kew) et Wikipédia. Photos et observations : iNaturalist (auteurs et licences indiqués sous chaque photo). Fond de carte : Natural Earth.</div>
        </div>
    )

    return (
        <div ref={ref} style={{ width: "100%", display: "flex", flexDirection: "column", gap: etroit ? 18 : 24 }}>
            <div style={{ display: "flex", gap: 12, flexWrap: "wrap", alignItems: "center", justifyContent: "space-between" }}>
                {recherche}
                <div style={{ display: "flex", gap: 6, flexWrap: etroit ? "nowrap" : "wrap", overflowX: etroit ? "auto" : "visible", maxWidth: "100%" }}>
                    {CATS.map(([c, t]) => <button key={c} style={puce(cat === c)} onClick={() => { setCat(c); if (g && c !== "Tous" && g.c !== c) setSel(null) }}>{t}</button>)}
                </div>
            </div>
            {carte}
            <div style={{ display: "flex", flexDirection: etroit ? "column" : "row", gap: etroit ? 28 : 48, alignItems: "flex-start", marginTop: etroit ? 0 : 8 }}>
                <div style={{ flex: etroit ? "none" : "1 1 0", width: etroit ? "100%" : undefined, minWidth: 0, position: etroit ? "static" : "sticky", top: 96 }}>{fiche}</div>
                <div style={{ flex: etroit ? "none" : "1.25 1 0", width: etroit ? "100%" : undefined, minWidth: 0 }}>{liste}</div>
            </div>
        </div>
    )
}

addPropertyControls(CarteMonde, {
    encre: { type: ControlType.Color, title: "Encre", defaultValue: "#1d1612" },
    vert: { type: ControlType.Color, title: "Points", defaultValue: "#4a7a36" },
    accent: { type: ControlType.Color, title: "Sélection", defaultValue: "#b5543a" },
    fond: { type: ControlType.Color, title: "Fond de section", defaultValue: "#efe6d6" },
})
